522	        madeFolder = true;
523	      } catch (error) {
524	        const code = (error as NodeJS.ErrnoException).code;
525	        return { ok: false, reason: code === "EEXIST" ? "exists" : "not-writable" };
526	      }
527	    }
528	    const undo = async (): Promise<void> => {
529	      await removeIdentity(path);
530	      if (madeFolder) await rmdir(path).catch(() => {});
531	    };
532	    const identity: WorkspaceIdentity = {
533	      version: 1,
534	      id: this.env.newId(),
535	      name: checked.name,
536	      color: input.color,
537	      initials: deriveInitials(checked.name),
538	      createdAt: WorkspaceRegistry.now(this.env),
539	    };
540	    try {
541	      await writeIdentity(path, identity);
542	    } catch {
543	      await undo();
544	      return { ok: false, reason: "not-writable" };
545	    }
546	    const entry = entryFromIdentity(identity, path, identity.createdAt);
547	    try {
548	      await this.update((key) => {
549	        // Re-checked inside the write: two creates cannot both take one name.
550	        if (validateWorkspaceName(checked.name, key.entries).ok === false)
551	          throw new NameTakenError();
552	        key.entries.push(entry);
553	      });
554	    } catch (error) {
555	      await undo();
556	      return { ok: false, reason: error instanceof NameTakenError ? "name-taken" : "not-writable" };
557	    }
558	    return { ok: true, entry };
559	  }
560	
561	  /**
562	   * Rename and/or recolor. The folder's `identity.json` is the authority (it travels with the
563	   * folder), so it is written first, atomically; the registry's cache follows. A change the
564	   * folder cannot take is refused whole. A workspace that is not connected is changed in the
565	   * registry only and carries `pendingIdentity`, so the change reaches the folder when it is
566	   * back instead of the folder's older file undoing it. Initials that were derived from the
567	   * old name follow the new one; initials the user chose stay.
568	   */
569	  async edit(id: string, patch: { name?: string; color?: string }): Promise<EditOutcome> {
570	    if (this.readOnly) return { ok: false, reason: "read-only" };
571	    const before = this.get(id);
572	    if (!before) return { ok: false, reason: "unknown" };
573	    let name = before.name;
574	    if (patch.name !== undefined) {
575	      const checked = validateWorkspaceName(patch.name, this.key.entries, id);
576	      if (!checked.ok) {
577	        return { ok: false, reason: checked.reason === "taken" ? "name-taken" : "invalid-name" };
578	      }
579	      name = checked.name;
580	    }
581	    let color = before.color;
582	    if (patch.color !== undefined) {
583	      if (!isTagColor(patch.color)) return { ok: false, reason: "invalid-color" };
584	      color = patch.color;
585	    }
586	    if (name === before.name && color === before.color) {
587	      return {
588	        ok: true,
589	        entry: before,
590	        savedToFolder:
591	          !before.pendingIdentity && !before.pendingColorUpgrade && !before.pendingInit,
592	      };
593	    }
594	
595	    // A probe first: a pending entry may adopt its folder's id, and it says whether to write.
596	    const probe = await this.availability(id);
597	    const entry = this.get(probe.id);
598	    if (!entry) return { ok: false, reason: "unknown" };
599	    const derived = entry.initials === undefined || entry.initials === deriveInitials(entry.name);
600	    const initials = derived ? deriveInitials(name) : entry.initials;
601	    const previous = await readIdentity(entry.path);
602	
603	    let savedToFolder = false;
604	    if (probe.availability.state === "available") {
605	      const next: WorkspaceIdentity =
606	        previous.kind === "ok"
607	          ? { ...previous.identity, name, color, ...(initials ? { initials } : {}) }
608	          : {
609	              version: 1,
610	              id: entry.id,
611	              name,
612	              color,
613	              ...(initials ? { initials } : {}),
614	              createdAt: entry.addedAt,
615	            };
616	      try {
617	        await writeIdentity(entry.path, next);
618	      } catch {
619	        return { ok: false, reason: "not-writable" };
620	      }
621	      savedToFolder = true;
622	    }
623	    try {
624	      await this.update((key) => {
625	        // Re-checked inside the write, like create: two edits cannot both take one name.
626	        if (!validateWorkspaceName(name, key.entries, entry.id).ok) throw new NameTakenError();
627	        const target = key.entries.find((e) => e.id === entry.id);
628	        if (!target) return;
629	        target.name = name;
630	        target.color = color;
631	        if (initials) target.initials = initials;
632	        // Still no identity.json in the folder when it was not written: the init stays pending,
633	        // or "Change folder…" would refuse the folder the workspace is later moved to.
634	        if (savedToFolder) delete target.pendingInit;
635	        // An edit owns the folder's identity from here, so a deferred upgrade has nothing left to decide.
636	        delete target.pendingColorUpgrade;
637	        if (savedToFolder) delete target.pendingIdentity;
638	        else target.pendingIdentity = true;
639	      });
640	    } catch (error) {
641	      // The folder must not keep a change the registry refused: the old file comes back, or,
642	      // when there was none, the one just written goes.
643	      if (savedToFolder && previous.kind === "ok") {
644	        await writeIdentity(entry.path, previous.identity).catch(() => {});
645	      } else if (savedToFolder && previous.kind === "absent") {
646	        await removeIdentity(entry.path);
647	      }
648	      return { ok: false, reason: error instanceof NameTakenError ? "name-taken" : "not-writable" };
649	    }
650	    return { ok: true, entry: this.get(entry.id) ?? entry, savedToFolder };
651	  }
652	
653	  /**
654	   * Is the folder there, with this entry's identity? Never creates the root. A pending entry
655	   * whose folder is back gets its identity written now, or adopts the one it finds there.
656	   * Resolves the entry's id afterwards (it changes only when a pending entry adopts one).
657	   */
658	  async availability(id: string): Promise<{ availability: Availability; id: string }> {
659	    const entry = this.get(id);
660	    if (!entry) return { availability: { state: "unavailable", reason: "missing" }, id };
661	    if (!(await isDirectory(entry.path))) {
662	      return { availability: { state: "unavailable", reason: "missing" }, id };
663	    }
664	    const identity = await readIdentity(entry.path);
665	    if (identity.kind === "unreadable") {
666	      return { availability: { state: "unavailable", reason: "unreadable" }, id };
667	    }
668	    if (identity.kind === "ok") {
669	      if (identity.identity.id === entry.id) {
670	        if (entry.pendingIdentity && !this.readOnly) {
671	          // Edited while the folder was away: the registry is newer, so the file catches up.
672	          try {
673	            await writeIdentity(entry.path, {
674	              ...identity.identity,
675	              name: entry.name,
676	              color: entry.color,
677	              ...(entry.initials ? { initials: entry.initials } : {}),
678	            });
679	            await this.refresh(() => {
680	              delete entry.pendingIdentity;
681	              delete entry.pendingColorUpgrade;
682	            });
683	          } catch {
684	            // stays pending; the next probe tries again
685	          }
686	          return { availability: { state: "available" }, id };
687	        }
688	        if (entry.pendingColorUpgrade && !this.readOnly && isOldDefault(identity.identity)) {
689	          // Nobody touched the folder since the upgrade was cached: the file takes the new color.
690	          try {
691	            await writeIdentity(entry.path, { ...identity.identity, color: entry.color });
692	            await this.refresh(() => void delete entry.pendingColorUpgrade);
693	          } catch {
694	            // stays pending; the next probe tries again
695	          }
696	          return { availability: { state: "available" }, id };
697	        }
698	        // The folder's file wins: the entry only caches it (renamed on another Mac). That also
699	        // drops a deferred color upgrade when the folder changed while it was away.
700	        const fresh = entryFromIdentity(identity.identity, entry.path, entry.addedAt);
701	        const stale =
702	          entry.pendingInit ||
703	          fresh.name !== entry.name ||
704	          fresh.color !== entry.color ||
705	          fresh.initials !== entry.initials ||
706	          entry.pendingColorUpgrade;
707	        if (stale) {
708	          await this.refresh(() => {
709	            delete entry.pendingInit;
710	            delete entry.pendingIdentity;
711	            delete entry.pendingColorUpgrade;
712	            delete entry.initials;
713	            Object.assign(entry, fresh);
714	          });
715	        }
716	        return { availability: { state: "available" }, id };
717	      }
718	      if (entry.pendingInit && !this.get(identity.identity.id)) {
719	        // Registered while unreachable, and an identity arrived meanwhile: that id wins.
720	        const adopted = identity.identity.id;
721	        await this.refresh((key) => {
722	          if (key.activeId === entry.id) key.activeId = adopted;
723	          if (key.legacyCloudOwnerId === entry.id) key.legacyCloudOwnerId = adopted;
724	          Object.assign(entry, entryFromIdentity(identity.identity, entry.path, entry.addedAt));
725	          delete entry.pendingInit;
726	        });
727	        return { availability: { state: "available" }, id: adopted };
728	      }
729	      return { availability: { state: "unavailable", reason: "different" }, id };
730	    }
731	    // No identity file (pending, or deleted by hand): Kaipu's own file, rewritten under the
732	    // registered id. A read-only folder stays usable, as before workspaces.
733	    if (!this.readOnly) {
734	      try {
735	        await writeIdentity(entry.path, {
736	          version: 1,
737	          id: entry.id,
738	          name: entry.name,
739	          color: entry.color,
740	          ...(entry.initials ? { initials: entry.initials } : {}),
741	          createdAt: entry.addedAt,
742	        });
743	        if (entry.pendingInit || entry.pendingIdentity || entry.pendingColorUpgrade) {
744	          await this.refresh(() => {
745	            delete entry.pendingInit;
746	            delete entry.pendingIdentity;
747	            delete entry.pendingColorUpgrade;
748	          });
749	        }
750	      } catch {
751	        // stays pending
752	      }
753	    }
754	    return { availability: { state: "available" }, id };
755	  }
756	
757	  /**
758	   * Add an existing folder. Creates only Kaipu's own files (`.kaipu/workspace/identity.json`)
759	   * and never touches the user's content. A folder with an identity is adopted: an id this
760	   * Mac knows at an unreachable path is a relocation, at a reachable one it is a copy, which
761	   * gets a new id. Does not switch.
762	   */
763	  async add(path: string): Promise<AddOutcome> {
764	    if (this.readOnly) return { ok: false, reason: "read-only" };
765	    const known = this.key.entries.find((e) => samePath(e.path, path));
766	    if (known) return { ok: true, entry: known, created: false };
767	    if (!(await isDirectory(path))) return { ok: false, reason: "not-writable" };
768	    const now = WorkspaceRegistry.now(this.env);
769	    const identity = await readIdentity(path);
770	    if (identity.kind === "unreadable") return { ok: false, reason: "unreadable" };
771	
772	    if (identity.kind === "ok") {
773	      const registered = this.get(identity.identity.id);
774	      if (registered) {
775	        const { availability } = await this.availability(registered.id);
776	        if (availability.state === "unavailable") {
777	          // The same folder at a new path (a renamed drive, a moved folder): relocate.
778	          await this.update(() => {
779	            Object.assign(
780	              registered,
781	              entryFromIdentity(identity.identity, path, registered.addedAt),
782	            );
783	            delete registered.pendingInit;
784	          });
785	          return { ok: true, entry: registered, created: false };
786	        }
787	        // A copy of a registered folder: same name, new id, so the two never share one.
788	        const copy: WorkspaceIdentity = {
789	          ...identity.identity,
790	          id: this.env.newId(),
791	          createdAt: now,
792	        };
793	        try {
794	          await writeIdentity(path, copy);
795	        } catch {
796	          return { ok: false, reason: "not-writable" };
797	        }
798	        const entry = entryFromIdentity(copy, path, now);
799	        await this.update((key) => void key.entries.push(entry));
800	        return { ok: true, entry, created: true };
801	      }
802	      const entry = entryFromIdentity(identity.identity, path, now);
803	      await this.update((key) => void key.entries.push(entry));
804	      return { ok: true, entry, created: true };
805	    }
806	
807	    const name = normalizeWorkspaceName(basename(path)) ?? DEFAULT_WORKSPACE_NAME;
808	    const minted: WorkspaceIdentity = {
809	      version: 1,
810	      id: this.env.newId(),
811	      name,
812	      color: nextWorkspaceColor(this.key.entries.map((e) => e.color)),
813	      initials: deriveInitials(name),
814	      createdAt: now,
815	    };
816	    try {
817	      await writeIdentity(path, minted);
818	    } catch {
819	      return { ok: false, reason: "not-writable" };
820	    }
821	    const entry = entryFromIdentity(minted, path, now);
822	    await this.update((key) => void key.entries.push(entry));
823	    return { ok: true, entry, created: true };
824	  }
825	
826	  /**
827	   * May `id` be pointed at `path`? Read-only: nothing is written, not even an identity file.
828	   * Only a folder whose `.kaipu/workspace/identity.json` carries this workspace's id qualifies.
829	   * An empty or plain folder is refused, never adopted: the workspace's items are not in it,
830	   * so every one of them would disappear from the library.
831	   */
832	  async checkRelocate(id: string, path: string): Promise<RelocateCheck> {
833	    if (this.readOnly) return { ok: false, reason: "read-only" };
834	    const entry = this.get(id);
835	    if (!entry) return { ok: false, reason: "unknown" };
836	    if (!(await isDirectory(path))) return { ok: false, reason: "not-a-folder" };
837	    const other = this.key.entries.find((e) => e.id !== id && samePath(e.path, path));
838	    if (other) return { ok: false, reason: "already-registered", workspaceName: other.name };
839	
840	    const identity = await readIdentity(path);
841	    if (identity.kind === "unreadable") return { ok: false, reason: "unreadable" };
842	    if (identity.kind === "ok") {
843	      return identity.identity.id === id
844	        ? { ok: true }
845	        : { ok: false, reason: "different", workspaceName: identity.identity.name };
846	    }
847	    // The folder it already points at, whose identity file was deleted by hand: a probe
848	    // rewrites it, so this is not a move.
849	    if (samePath(entry.path, path)) return { ok: true };
850	    if (await isDirectory(join(path, ".kaipu"))) {
851	      // A workspace registered while its folder was away never got an identity.json, so a
852	      // folder with Kaipu items and none is exactly where it can now be: the probe after the
853	      // move writes the file under the registered id. Any other workspace has an identity to
854	      // match, so a folder without one is not its own.
855	      return entry.pendingInit ? { ok: true } : { ok: false, reason: "has-items-no-identity" };
856	    }
857	    return { ok: false, reason: "not-a-workspace" };
858	  }
859	
860	  /**
861	   * "Change folder…": point `id` at the folder where it now lives (moved in Finder, put in a
862	   * Google Drive folder, a drive mounted elsewhere). Only the registry changes: no file is
863	   * moved, copied or written. Name, color and id stay. The active workspace's path is mirrored
864	   * into `vaultDirectory`; the caller runs that one inside the switch transaction.
